<?php
function img_ok($f){if(empty($f['tmp_name'])||($f['error']??4)===UPLOAD_ERR_NO_FILE)return null;if($f['error']!==UPLOAD_ERR_OK||$f['size']>8*1024*1024)return 'each image must be under 8 MB (and within the server upload limit).';$i=@getimagesize($f['tmp_name']);if(!$i||!in_array($i[2],[IMAGETYPE_JPEG,IMAGETYPE_PNG,IMAGETYPE_WEBP,IMAGETYPE_GIF]))return 'please choose a JPG, PNG, WebP or GIF picture.';if(!function_exists('imagecreatefromstring')&&$i[2]!=IMAGETYPE_JPEG)return 'this server can only accept JPG pictures.';return true;}
function img_save($f,$dest,$max=1000){$s=@file_get_contents($f['tmp_name']);if(function_exists('imagecreatefromstring')&&($im=@imagecreatefromstring($s))){$w=imagesx($im);$h=imagesy($im);$r=min(1,$max/max($w,$h));$n=imagecreatetruecolor((int)round($w*$r),(int)round($h*$r));imagefill($n,0,0,0xFFFFFF);imagecopyresampled($n,$im,0,0,0,0,(int)round($w*$r),(int)round($h*$r),$w,$h);imagejpeg($n,$dest,85);}else move_uploaded_file($f['tmp_name'],$dest);}
